def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_count = 0
    weak_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                weak_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid >= 60:
                    aggressive_count += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = supply <= 17
    abundant = supply >= 22

    critical = hp <= 2 or no_water >= 2
    urgent = hp <= 4 or no_water >= 1

    if critical:
        target = max(72.0, highest_prev + 2.5)
        if scarcity:
            target = max(target, 88.0)
        return float(min(budget, target))

    if urgent:
        target = max(46.0, avg_prev + 3.0)
        if highest_prev >= 100:
            target = 58.0 if hp > 3 else 92.0
        if scarcity:
            target += 8.0
        return float(min(budget, target))

    if highest_prev >= 120:
        if abundant or weak_count >= 1:
            return float(min(budget, 12.0))
        return float(min(budget, 24.0))

    if highest_prev >= 90:
        if scarcity:
            return float(min(budget, 34.0))
        return float(min(budget, 20.0))

    base = 18.0
    if scarcity:
        base = 30.0
    elif abundant:
        base = 14.0

    if aggressive_count == 0 and avg_prev > 0:
        base = max(base, avg_prev + 1.5)

    if day >= 8 and hp <= 6:
        base += 8.0

    reserve_cap = budget
    if day <= 3:
        reserve_cap = min(reserve_cap, DAILY_SALARY * 0.65)
    elif day <= 7:
        reserve_cap = min(reserve_cap, DAILY_SALARY * 0.85)

    return float(min(reserve_cap, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday's bids to infer aggressiveness
    cindy_bid = None
    max_prev_bid = 0.0
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is None:
            continue
        try:
            b = float(b)
        except Exception:
            continue
        if b > max_prev_bid:
            max_prev_bid = b
        if str(opp_id).lower() == 'cindy':
            cindy_bid = b

    # Pressure signal: Cindy's high bid indicates others may also bid high
    pressure = 0.0
    if cindy_bid is not None:
        pressure = 1.0 if cindy_bid >= DAILY_SALARY * 0.9 else 0.5 if cindy_bid >= DAILY_SALARY * 0.6 else 0.0
    if pressure == 0.0 and max_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 0.5

    # Supply-based aggressiveness: higher supply reduces need to overbid
    # Map supply to a multiplier in [0.85, 1.15]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    if t < 0.0:
        t = 0.0
    if t > 1.0:
        t = 1.0

    supply_mult = 0.95 + 0.2 * t  # higher supply => slightly higher willingness to pay (to secure HP)

    # HP urgency: if low HP or building no-water days, bid more
    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 4:
        urgency = 0.7
    elif hp <= 6:
        urgency = 0.4
    else:
        urgency = 0.2

    if no_water_days >= 2:
        urgency = max(urgency, 0.8)

    # Base bid target
    # If pressure high, try to outbid slightly below the top aggressiveness threshold.
    if pressure >= 0.5:
        target = DAILY_SALARY * (0.55 + 0.35 * urgency) * supply_mult
        # If we know someone previously bid very high, nudge upward but cap.
        if max_prev_bid > 0:
            target = max(target, min(DAILY_SALARY * 0.75, max_prev_bid * 0.95))
    else:
        target = DAILY_SALARY * (0.45 + 0.35 * urgency) * supply_mult

    # Ensure we don't exceed budget
    if budget <= 0:
        return 0.0

    # Cap to keep some budget for later days
    # When HP is critical, allow higher spend.
    budget_cap = DAILY_SALARY * (0.95 if urgency >= 0.8 else 0.7)
    bid = min(budget, min(target, budget_cap))

    # If we are extremely low HP, spend more aggressively
    if hp <= 1:
        bid = min(budget, DAILY_SALARY * 0.98)

    # Avoid negative/NaN
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if not prev_bids:
        return min(my_status['budget'], 60.0)

    avg_prev = sum(prev_bids) / len(prev_bids)
    max_prev = max(prev_bids)

    if my_status['hp'] < 4:
        return min(my_status['budget'], max_prev + 10.0)

    if day_context['supply'] < WATER_REQ * (len(alive_opponents) + 1):
        return min(my_status['budget'], max_prev + 5.0)

    return min(my_status['budget'], max(avg_prev * 0.9, 40.0))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {aid: opp for aid, opp in opponents_status.items() if opp['alive']}

    # Gather yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5  # default moderate

    if hp <= 2 or no_water_days >= 2:
        # Need water urgently
        base_bid = DAILY_SALARY * 0.9
    elif yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev >= DAILY_SALARY * 0.86:  # ~120
            if hp > 4:
                base_bid = DAILY_SALARY * 0.3
            else:
                base_bid = DAILY_SALARY * 0.8
        else:
            base_bid = max(DAILY_SALARY * 0.5, highest_prev + 1.5)
    else:
        # No history, play safe
        base_bid = DAILY_SALARY * 0.55

    # Ensure bid does not exceed budget and is non-negative
    bid = min(budget, base_bid)
    return max(int(bid), 0)
